        stoneToken.transfer(_msgSender(), amount);

        emit StoneTokensRedeemed(_msgSender(), amount);
    }

    /**
     * @dev Sets the maximum total value that can be staked in ETH.
     * @param newLimit The new maximum stake limit in ETH.
